SELECT 'coin' AS layer,evaluation_version,count(*) AS samples,md5(string_agg(md5(payload::text),',' ORDER BY snapshot_set_id,symbol)) AS payload_digest FROM research_watch_scan_formula_samples WHERE snapshot_set_id<=1306 AND status='READY' GROUP BY evaluation_version UNION ALL SELECT 'timeframe' AS layer,evaluation_version,count(*) AS samples,md5(string_agg(md5(payload::text),',' ORDER BY snapshot_set_id,symbol)) AS payload_digest FROM research_watch_scan_tf_formula_samples WHERE snapshot_set_id<=1306 AND status='READY' GROUP BY evaluation_version ORDER BY layer,evaluation_version
